// nf-core modules test centrifuge/kreport
nextflow_process {

    name "Test Process CENTRIFUGE_KREPORT"
    script "../main.nf"
    process "CENTRIFUGE_KREPORT"

    tag "modules"
    tag "modules_nfcore"
    tag "centrifuge"
    tag "centrifuge/centrifuge"
    tag "centrifuge/kreport"

    test("sarscov2_fastq_se") {
        def db
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            db = extract(modules_testdata_base_path + 'delete_me/minigut_cf.tar.gz').resolve('minigut_cf')
            run("CENTRIFUGE_CENTRIFUGE") {
                script "../../../centrifuge/centrifuge/main.nf"
                process {
                    """
                    input[0] = [
                        [id: 'test', single_end: true],
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)
                    ]
                    input[1] = file('${db}')
                    input[2] = true
                    input[3] = true
                    """
                }
            }
        }


        when {
            process {
                """
                input[0] = CENTRIFUGE_CENTRIFUGE.out.results
                input[1] = file('${db}')
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    file(process.out.kreport[0][1]).name,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match() }
            )
        }

    }

    test("sarscov2 - bam - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [ [id: 'test', single_end: true], [] ]
                input[1] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}
